const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim();
    if (!input) return;
    let n = BigInt(input);
    let min = 10000000000n;
    let max;
    let a, b, c, k, diff;

    for (let i = 1n; i * i * i <= n; i++) {
        if (n % i === 0n) {
            for (let j = i; j * j <= n / i; j++) {
                if (n % j === 0n) {
                    k = n / (i * j);
                    a = i + 1n;
                    b = j + 2n;
                    c = k + 2n;
                    if ((a - 1n) * (b - 2n) * (c - 2n) === n) {
                        diff = a * b * c - n;
                        if (min > diff) {
                            min = diff;
                        }
                    }
                }
            }
        }
    }

    max = 9n * (n + 1n) - n;
    console.log(`${min} ${max}`);
}

main();

